    // Constructor //
    explicit Phase2TrackerBXHistogram(const edm::ParameterSet&);
    // Destructor //
    ~Phase2TrackerBXHistogram() override;
    // Initialize run parameters //
    void dqmBeginRun(const edm::Run& iRun, const edm::EventSetup& iSetup) override;
    // Analyse : loop over delays and use runSimHit for each //
    void analyze(const edm::Event& iEvent, const edm::EventSetup& iSetup) override;
    // Logic to run over hits and check triggering //
    template <typename T>
    void runSimHit(T isim,double offset, const TrackerTopology* tTopo,const TrackerGeometry* tGeom);
    
    // Logics to check whether pixel or strip hit and get track pT //
    bool isPixel(const DetId& detId);
    bool isStrip(const DetId& detId);
    bool is2S(const DetId& detId, const TrackerGeometry* tGeom);
    bool isPSP(const DetId& detId, const TrackerGeometry* tGeom);
    bool isPSS(const DetId& detId, const TrackerGeometry* tGeom);
    float getSimTrackPt(EncodedEventId event_id, unsigned int tk_id);
    
    // Structures //
    struct HistModes{ // Base histogram containers
        MonitorElement* Sampled;
        MonitorElement* Sampled_2S;
        MonitorElement* Sampled_PSp;
        MonitorElement* Sampled_PSs;
        MonitorElement* Latched;
        MonitorElement* Latched_2S;
        MonitorElement* Latched_PSp;
        MonitorElement* Latched_PSs;
        MonitorElement* Simple_PSp;
    };
    
    struct HitsPositions{  // Save hit positions
        MonitorElement* positions3D;
        MonitorElement* positions3D_2S;
        MonitorElement* positions3D_PSp;
        MonitorElement* positions3D_PSs;
        MonitorElement* positions2D;
        MonitorElement* positions2D_2S;
        MonitorElement* positions2D_PSp;
        MonitorElement* positions2D_PSs;
        MonitorElement* positions2DAbs;
        MonitorElement* positions2DAbs_2S;
        MonitorElement* positions2DAbs_PSp;
        MonitorElement* positions2DAbs_PSs;
    };
    
